struct Point {
    int x;
    int y;
    struct Point* next; // Self-referential
};

// Typedef for cleaner naming
typedef struct {
    char name[50];
    int id;
} Student;

struct Point p1 = {10, 20, NULL};
Student s1 = {"Alice", 101};

// Access via pointer
struct Point* ptr = &p1;
ptr->y = 50;

union Data {
    int i;
    float f;
    char s[10];
};

union Data d;
// d will occupy sizeof(char[10]) memory
d.i = 42;
// d.f is now corrupted
d.f = 3.14f;
// d.i is now corrupted
// Only one member is valid at a time
d.s[0] = 'A';
